// === FORMATEAR ERROR PARA ADMINISTRADOR ===
// Recibe el contexto del error de n8n y arma un mensaje claro.
const e = $input.first().json;
const exec    = e.execution  || {};
const wf      = e.workflow   || {};
const errData = exec.error   || {};

const ts    = new Date().toLocaleString('es-CO', {timeZone:'America/Bogota'});
const nodo  = errData.node?.name  || exec.lastNodeExecuted || 'desconocido';
const msg   = errData.message     || 'Sin detalle';
const wfName= wf.name             || 'WF_Principal_DeliveryBot';
const execId= exec.id             || '?';

const texto = `⚠️ <b>ERROR EN DELIVERYBOT</b>\n\n` +
  `📋 Workflow: <b>${wfName}</b>\n` +
  `🔴 Nodo: <code>${nodo}</code>\n` +
  `💬 Error: ${msg}\n` +
  `🕐 Hora: ${ts}\n` +
  `🆔 Ejecución: <code>${execId}</code>\n\n` +
  `Revisa Executions en n8n para ver el detalle completo.`;

return [{ json: { texto, wfName, nodo, execId } }];
